# ------------------------------------------------------------------------------------------------- apply --
ORIGINAL = {}   # key -> the wording a line had before this module rewrote it


def apply_text(en, family):
    """Lays LINES over strings.EN. The replaced wording becomes the family-friendly wording, unless the line
    already has one. Called once at the end of strings.py."""
    for key, line in LINES.items():
        if key not in en:
            continue
        ORIGINAL[key] = en[key]
        family.setdefault(key, en[key])
        en[key] = line


def apply_say(say, say_family):
    """Lays SPOKEN over cast.SAY. Where a line's old wording is now its family wording, the old spoken
    version goes with it (cast.SAY_FAMILY), so the family-friendly voice keeps its number-free clips.
    Called once in cast.py, after SAY and SAY_FAMILY are built."""
    for key, spoken in SPOKEN.items():
        if key in say:
            say_family.setdefault(key, say[key])
        say[key] = spoken


def family_gift_say(family):
    """The Mayor's banked thanks, said without the receipt, for their family wording too."""
    return {k: v.split("+{gain}. ", 1)[1] for k, v in family.items()
            if k.startswith(("m.gift.warm.", "m.gift.delighted.")) and "+{gain}. " in v}


def delivery(own):
    """A character's delivery note with the house style added (TTS-2 only; Flash ignores both)."""
    own = " ".join(str(own or "").split())
    return (own + "; " + DELIVERY) if own else DELIVERY
